            }
        });

        app.get("/reservations/:id/document", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                String receipt = hotelService.getReceipt(id);
                ctx.result(receipt);
            } catch (IllegalArgumentException e) {
