            try {
                String monthStr = ctx.queryParam("month");
                if (monthStr == null || monthStr.isEmpty()) {
                    throw new BadRequestResponse(ErrorResponse.error("INVALID_REQUEST", "Missing month parameter"));
                }

                String[] parts = monthStr.split("-");
                if (parts.length != 2) {
                    throw new BadRequestResponse(ErrorResponse.error("INVALID_REQUEST", "Invalid month format"));
