app.get("/reports/revenue", ctx -> {
    String monthStr = ctx.queryParam("month");
    if (monthStr == null || monthStr.isEmpty()) {
        ctx.status(400);
        ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing month parameter"));
        return;
    }

    String[] parts = monthStr.split("-");
    if (parts.length != 2) {
        ctx.status(400);
        ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
        return;
    }

    try {
        int year = Integer.parseInt(parts[0]);
        int month = Integer.parseInt(parts[1]);

        if (month < 1 || month > 12) {
            ctx.status(400);
            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month value"));
            return;
        }

        String report = hotelService.getRevenueReport(year, month);
        ctx.contentType("text/csv; charset=utf-8");
        ctx.result(report);
    } catch (NumberFormatException e) {
        ctx.status(400);
        ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
    }
});

